require '../../includes/header.php';require '../../includes/role_guard.php';requireRole(['admin']);require '../../includes/db.php';require_once '../../includes/case_workflow.php';
function count_query(mysqli$c,string$sql):int{return(int)$c->query($sql)->fetch_row()[0];}
$metrics=['families'=>count_query($conn,'SELECT COUNT(*) FROM ip_families'),'members'=>count_query($conn,'SELECT COUNT(*) FROM ip_family_members'),'cases'=>count_query($conn,"SELECT COUNT(*) FROM case_applications WHERE status NOT IN('resolved','closed')"),'land_queue'=>count_query($conn,"SELECT COUNT(*) FROM case_applications WHERE case_type='land_dispute' AND assigned_to='assessor' AND status NOT IN('resolved','closed')"),'parcels'=>count_query($conn,'SELECT COUNT(*) FROM ip_land_parcels'),'tax'=>count_query($conn,'SELECT COUNT(*) FROM tax_declarations'),'users'=>count_query($conn,"SELECT COUNT(*) FROM users WHERE status='active'")];
