<div class="row g-3 mb-4"><?php foreach([['Registered Families',$metrics['families'],'people-fill'],['Family Members',$metrics['members'],'person-vcard'],['Active Cases',$metrics['cases'],'folder2-open'],['Assessor Land Queue',$metrics['land_queue'],'clipboard-check']]as[$label,$value,$icon]):?><div class="col-6 col-xl-3"><div class="card-box metric-card d-flex justify-content-between"><div><div class="metric-label"><?=$label?></div><div class="metric-value"><?=number_format($value)?></div></div><div class="metric-icon"><i class="bi bi-<?=$icon?>"></i></div></div></div><?php endforeach;?></div>
